function drawFunnel(c){clearNative();const rows=funnel(c),counts=c.steps.map((_,i)=>rows.filter(r=>r.times.length>i).length),complete=rows.filter(r=>r.times.length===c.steps.length),pending=rows.filter(r=>r.pending).length;const losses=c.steps.slice(1).map((_,i)=>rows.filter(r=>r.times.length===i+1&&!r.pending).length);const max=Math.max(...losses),mi=losses.indexOf(max);const context=`${date(c.start)}–${date(c.end-day)} · ${c.hours} 小时内 · ${c.source==='all'?'全部来源':c.source}`;
$('#as-output').innerHTML=`<div class="a-context"><span class="a-chip">顺序漏斗 · 按用户去重</span><span>${context}</span></div><div class="a-summary">${stat('整体转化率',pct(complete.length,rows.length),`${complete.length} / ${rows.length} 位入组用户`)}${stat('完成转化用户',fmt(complete.length),'依次完成全部步骤')}${stat('转化耗时中位数',median(complete.map(r=>r.times.at(-1)-r.times[0])),'仅统计完成转化的用户')}</div><div class="a-card"><div class="a-cardhead"><div class="a-tabs"><button class="a-tab cursor-interaction" data-view="conversion" aria-pressed="${view==='conversion'}">漏斗转化</button><button class="a-tab cursor-interaction" data-view="trend" aria-pressed="${view==='trend'}">转化趋势</button></div><span class="a-muted">${pending?pending+' 位用户窗口进行中':'全部转化窗口已结束'}</span></div><div class="a-chart" id="as-chart"></div><div class="a-insight">最大已确认流失：步骤 ${mi+1} → ${mi+2}，${max} 人。<button class="a-link cursor-interaction" data-loss="${mi}">查看流失用户 ↗</button></div></div><div class="a-card"><div class="a-cardhead"><h2>步骤转化明细</h2><span class="a-muted">点击人数下钻</span></div>${table(['步骤','到达用户','上一步转化','整体占比','已确认流失'],c.steps.map((s,i)=>[`${i+1}. ${names[s]}`,`<button class="a-tablelink cursor-interaction" data-reached="${i}">${fmt(counts[i])}</button>`,i?pct(counts[i],counts[i-1]):'—',pct(counts[i],counts[0]),i<c.steps.length-1?`<button class="a-tablelink cursor-interaction" data-loss="${i}">${losses[i]} 人</button>`:'—']))}</div><div class="a-card"><div class="a-cardhead"><h2>按登录进入来源比较</h2><span class="a-muted">同一漏斗 · 同一窗口</span></div>${table(['来源','入组用户','完成用户','整体转化率','查看人群'],[...new Set(users.flatMap(u=>[u.source,...u.events.map(e=>e.entry_source)].filter(Boolean)))].filter(s=>c.source==='all'||c.source===s).map(s=>{const a=rows.filter(r=>r.u.source===s),b=a.filter(r=>r.times.length===c.steps.length);return[s,a.length,b.length,pct(b.length,a.length),`<button class="a-tablelink cursor-interaction" data-group="${s}">查看用户 ↗</button>`]}))}</div><details class="a-card a-details"><summary>计算口径与数据准备</summary><p>以统计期内首次匹配第一步的时间入组；后续事件须按配置顺序发生，允许中间穿插其他事件。转化窗口从第一步开始计算，可跨统计期末。</p><p>窗口未结束且未完成下一步的用户为进行中，暂不判定流失。转化率包括进行中批次，仍可能变化。</p><p>默认AI漏斗依次统计登录成功、Token详情、AI策略成功开启和有效分析；非AI路径可删除AI步骤观察。</p><p>登录成功仅统计身份验证成功，不包含已有登录态恢复；AI开启需后台确认成功。这里的用户和事件均为合成数据。</p></details>`;
const chart=()=>{clearNative();if(view==='conversion')showFunnel(c,rows,counts);else $('#as-chart').innerHTML=`<p class="a-muted">按第一步入组日期 · 整体转化率</p>`+Array.from({length:c.range},(_,i)=>{const d=daynum(c.start)+i,rr=rows.filter(r=>daynum(r.times[0])===d),nn=rr.filter(r=>r.times.length===c.steps.length).length;return `<div class="a-trendrow"><span>${date(c.start+i*day)}</span><div class="a-track"><div class="a-fill" style="width:${rr.length?nn/rr.length*100:0}%"></div></div><span>${pct(nn,rr.length)} · ${nn}/${rr.length}</span></div>`}).join('');$$('[data-bar]').forEach(b=>b.onclick=()=>drill(names[c.steps[+b.dataset.bar]],rows.filter(r=>r.times.length>+b.dataset.bar),'已到达当前步骤'))};chart();$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;$$('[data-view]').forEach(x=>x.setAttribute('aria-pressed',x===b));chart()});$$('[data-reached]').forEach(b=>b.onclick=()=>drill(names[c.steps[+b.dataset.reached]],rows.filter(r=>r.times.length>+b.dataset.reached),'已到达当前步骤'));$$('[data-loss]').forEach(b=>b.onclick=()=>drill(`步骤 ${+b.dataset.loss+1} → ${+b.dataset.loss+2} 流失用户`,rows.filter(r=>r.times.length===+b.dataset.loss+1&&!r.pending),'窗口已结束且未到达下一步'));$$('[data-group]').forEach(b=>b.onclick=()=>drill(b.dataset.group+' 来源用户',rows.filter(r=>r.u.source===b.dataset.group),'按入组用户的登录进入来源分组'));
}
function drawRetention(c){
clearNative();const cohorts=buildCohorts(users,{startAt:c.start,endAt:c.end,asOf:asof,initialEvent:c.initial,returningEvent:c.returning,sourceFilter:c.source}).map(co=>({...co,d:daynum(co.start)}));
const returned=retainedUsers,mature=periodComplete,observed=periodObserved;
const candidates=cohorts.filter(co=>co.users.length),chosen=[...candidates].reverse().find(co=>mature(co,7))||candidates[0];let continuous=false;
const drillRows=arr=>arr.map(u=>({u,displaySource:u.events.find(e=>e.type===c.initial).entry_source}));
$('#as-output').innerHTML=`<div class="a-context"><span class="a-chip">按首次行为来源分组 · 自然日留存</span><span>${date(c.start)}–${date(c.end-day)} · ${c.source==='all'?'全部来源':c.source}</span></div><div class="a-card"><div class="a-cardhead"><label style="margin:0">当前分析批次<select id="as-cohort-picker">${candidates.map(co=>`<option value="${co.d}" ${co===chosen?'selected':''}>${date(base+co.d*day)} · ${co.users.length} 人${mature(co,7)?' · 已成熟':''}</option>`).join('')}</select></label><div class="a-tabs"><button class="a-tab cursor-interaction" data-retmode="daily" aria-pressed="true">日留存</button><button class="a-tab cursor-interaction" data-retmode="continuous" aria-pressed="false">连续留存</button></div></div></div><div class="a-summary" id="as-ret-summary"></div><div class="a-card"><div class="a-cardhead"><h2 id="as-ret-title">日留存曲线</h2><span class="a-muted">指标与图形使用同一批次</span></div><div class="a-chart"><div id="as-ret-chart" style="width:100%;height:300px" role="img" aria-label="选中批次的日留存率曲线"></div></div><div class="a-insight" id="as-ret-note"></div></div><div class="a-card"><div class="a-cardhead"><h2 id="as-cohort-title">日留存批次表</h2><span class="a-muted">点击日期联动上方；点击格子查看用户</span></div><div class="a-heat-legend"><span>完整日：低 <i></i> 高</span><span>虚线：进行中</span><span>灰色：未到观察期</span></div><div id="as-cohort-table"></div></div><details class="a-card a-details"><summary>统计口径</summary><p>日留存：Dn 当天回来即计入，不要求 D1 至 Dn 连续回来。连续留存：D1 至 Dn 每天都完成回访行为。</p><p>所有百分比均以该批次 D0 去重人数为分母。7 日内回访率是 D1–D7 至少回来一次的去重人数占比。</p><p>按首次行为的来源分组；默认首次行为为有效分析，因此对应 V1 的 first_entry_source。回访可来自任何来源和币种。</p><p>未到观察日显示 —，当前观察日显示进行中；窗口尚未结束时，不显示最终 7 日结果。首次行为以接口提供的历史记录为准。</p></details>`;
if(!chosen){$('#as-ret-summary').innerHTML=stat('首次行为人数','0','当前筛选没有批次');$('#as-ret-note').textContent='当前筛选没有首次行为用户。';return}
const coSelected=()=>candidates.find(x=>x.d===+$('#as-cohort-picker').value)||chosen;
function renderTable(){
$('#as-cohort-title').textContent=continuous?'连续留存批次表':'日留存批次表';
$('#as-cohort-table').innerHTML=table(['首次日期','D0 人数',...Array.from({length:7},(_,i)=>(continuous?'连续 ':'')+'D'+(i+1))],cohorts.map((co,i)=>[`<button class="a-tablelink cursor-interaction" data-select-co="${co.d}" ${co.users.length?'':'disabled'}>${date(base+co.d*day)}${co.d===coSelected().d?' · 当前':''}</button>`,co.users.length,...Array.from({length:7},(_,j)=>{let d=j+1;if(!co.users.length||!observed(co,d))return '<span class="a-heat-unavailable" title="未到观察期或无入组用户">—</span>';let n=returned(co,d,continuous).length;return `<button class="a-heat cursor-interaction ${mature(co,d)?'is-complete':'is-pending'}" style="--heat-intensity:${Math.round(n/co.users.length*75)+5}%" aria-label="${date(base+co.d*day)} D${d} 留存 ${pct(n,co.users.length)}，${n}人，${mature(co,d)?'观察完成':'进行中'}" data-co="${i}" data-day="${d}">${pct(n,co.users.length)}<small>${n} 人${mature(co,d)?'':' · 进行中'}</small></button>`})]));
$$('[data-select-co]').forEach(b=>b.onclick=()=>{$('#as-cohort-picker').value=b.dataset.selectCo;render()});$$('[data-co]').forEach(b=>b.onclick=()=>{const co=cohorts[+b.dataset.co],n=+b.dataset.day;drill(date(base+co.d*day)+' · '+(continuous?'连续 ':'')+'D'+n,drillRows(returned(co,n,continuous)),`${co.users.length} 位 D0 用户 · 按首次行为来源${mature(co,n)?'':' · 观察进行中'}`)})}
function render(){clearNative();closeDrill();const co=coSelected(),n0=co.users.length;
const d1=returned(co,1).length,seven=co.users.filter(u=>u.events.some(e=>e.type===c.returning&&daynum(e.t)>co.d&&daynum(e.t)<=co.d+7)).length,con7=returned(co,7,true).length;
$('#as-ret-summary').innerHTML=stat('当前批次 D0 人数',fmt(n0),date(base+co.d*day)+' · 首次行为用户')+stat('D1 留存率',observed(co,1)?pct(d1,n0):'—',observed(co,1)?`${d1} / ${n0}${mature(co,1)?' · 完整日':' · 进行中'}`:'尚未到观察日')+stat(continuous?'连续 7 日留存率':'7 日内回访率',mature(co,7)?pct(continuous?con7:seven,n0):'—',mature(co,7)?`${continuous?con7:seven} / ${n0} · 同一批次`:'观察窗口进行中');
$('#as-ret-title').textContent=continuous?'连续留存漏斗':'日留存曲线';$('#as-ret-note').textContent=continuous?'从 D1 起每天都回来才进入下一层；未到观察日的层暂不显示。点击层查看用户。':'每天独立观察，留存率可以回升。点击数据点查看当天回访用户；进行中数据尚未定稿。';
renderTable();const host=$('#as-ret-chart');host.style.height=continuous?'470px':'300px';host.setAttribute('aria-label',continuous?'同一批次连续留存漏斗':'同一批次 D0 到 D7 日留存率曲线');
if(!globalThis.echarts){host.innerHTML='<p class="a-status">图表组件未加载，请稍后运行分析重试。可查看下方批次表。</p>';return}
const color=key=>{const p=document.createElement('span');p.style.color=`var(${key})`;root.appendChild(p);const v=getComputedStyle(p).color;p.remove();return v};
const data=Array.from({length:8},(_,d)=>({d,name:d===0?'D0':(continuous?'连续 ':'')+'D'+d,num:d===0?n0:returned(co,d,continuous).length,ready:d===0||observed(co,d),done:d===0||mature(co,d)}));nativeChart=echarts.init(host,null,{renderer:'svg'});
const paint=()=>{if(!nativeChart||!host.isConnected)return;const tooltip={trigger:'item',confine:true,backgroundColor:color('--a-panel'),borderColor:color('--a-border'),textStyle:{color:color('--a-text')},formatter:p=>{const x=data[p.dataIndex];return `${x.name}<br/>${x.num} / ${n0} 人<br/>${pct(x.num,n0)}<br/>${x.done?'观察已完成':'进行中'}`}};let option;
if(continuous){const dd=data.filter(x=>x.ready);option={animation:false,aria:{enabled:true},tooltip,series:[{type:'funnel',sort:'none',top:10,bottom:10,left:'4%',width:'56%',min:0,max:n0,minSize:'0%',maxSize:'100%',gap:7,label:{show:true,position:'right',color:color('--a-text'),fontSize:12,lineHeight:18,formatter:p=>`${p.name}${dd[p.dataIndex].done?'':' · 进行中'}\n${p.value} 人 · ${pct(p.value,n0)}`},labelLine:{length:12,lineStyle:{color:color('--a-muted'),width:1}},itemStyle:{color:color('--a-accent'),borderWidth:0},data:dd.map(x=>({name:x.name,value:x.num}))}]}}
else{option={animation:false,aria:{enabled:true},tooltip,grid:{left:48,right:28,top:36,bottom:40},xAxis:{type:'category',name:'回访日',nameLocation:'middle',nameGap:26,data:data.map(x=>'D'+x.d),axisLabel:{color:color('--a-muted'),fontSize:12},axisLine:{lineStyle:{color:color('--a-border')}}},yAxis:{type:'value',min:0,max:100,name:'留存率（%）',nameTextStyle:{color:color('--a-muted')},axisLabel:{color:color('--a-muted'),formatter:'{value}%'},splitLine:{lineStyle:{color:color('--a-border')}}},series:[{type:'line',connectNulls:false,symbolSize:9,smooth:false,lineStyle:{color:color('--a-accent'),width:2},itemStyle:{color:color('--a-accent')},data:data.map(x=>({value:x.ready?+(x.num/n0*100).toFixed(1):null,symbol:x.done?'circle':'emptyCircle'}))}]}}
nativeChart.setOption(option,true)};paint();nativeChart.on('click',p=>{const x=data[p.dataIndex];if(!x.ready)return;drill(date(base+co.d*day)+' · '+x.name,drillRows(x.d===0?co.users:returned(co,x.d,continuous)),`D0 ${n0} 人 · 按首次行为来源`)});nativeResize=new ResizeObserver(()=>nativeChart&&nativeChart.resize());nativeResize.observe(host);themeHandler=paint;themeMedia.addEventListener('change',themeHandler)}
$('#as-cohort-picker').onchange=render;$$('[data-retmode]').forEach(b=>b.onclick=()=>{continuous=b.dataset.retmode==='continuous';$$('[data-retmode]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()});render();
}
let tradeChart=null,tradeResize=null,tradeTheme=null;
function clearTrade(){if(tradeResize){tradeResize.disconnect();tradeResize=null}if(tradeChart){tradeChart.dispose();tradeChart=null}if(tradeTheme){themeMedia.removeEventListener('change',tradeTheme);tradeTheme=null}}
const dailyTrades=(dataStore.trades||[]).filter(t=>t.status==='confirmed').map(t=>({u:users.find(u=>u.id===t.user_id)||{id:t.user_id},date:Math.floor((t.confirmed_at+7*3600000)/day)*day-7*3600000,volume:t.volume_usd}));
function tradingContribution(c){const analyzed=new Set(users.filter(u=>u.events.some(e=>e.type==='chip'&&e.t<c.end)).map(u=>u.id));const records=dailyTrades.filter(r=>r.date>=c.start&&r.date<c.end);const days=Array.from({length:c.range},(_,i)=>{const date=c.start+i*day,rs=records.filter(r=>r.date===date);const a=rs.filter(r=>analyzed.has(r.u.id)).reduce((a,r)=>a+r.volume,0),b=rs.filter(r=>!analyzed.has(r.u.id)).reduce((a,r)=>a+r.volume,0);return{date,a,b,total:a+b}});const a=days.reduce((a,d)=>a+d.a,0),b=days.reduce((a,d)=>a+d.b,0);return{analyzed,records,days,a,b,total:a+b}}
const money=n=>'$'+fmt(n);
function tradeMarkup(tx,c){if(!Array.isArray(dataStore.trades))return '';return `<section class="a-card" id="as-trade-module"><div class="a-cardhead"><div><h2>有效分析用户交易贡献</h2><p class="a-muted">全平台 · ${date(c.start)}–${date(c.end-day)} · 计价单位 USD</p></div><span class="a-chip">平台总交易量 ${money(tx.total)}</span></div><div class="a-north-share"><div class="a-north-share-labels"><span>有效分析用户 <strong>${pct(tx.a,tx.total)}</strong></span><span>其他用户 <strong>${pct(tx.b,tx.total)}</strong></span></div>${tx.total?`<div class="a-north-share-track" role="img" aria-label="有效分析用户交易量占比 ${pct(tx.a,tx.total)}，其他用户 ${pct(tx.b,tx.total)}"><span style="width:${tx.a/tx.total*100}%;background:var(--a-accent)"></span><span style="width:${tx.b/tx.total*100}%;background:var(--a-green)"></span></div>`:'<p class="a-muted">本期没有已确认成交，占比不适用。</p>'}</div><div class="a-summary" style="border:0;border-radius:0;margin:0">${stat('截至期末有效分析用户交易量',`<button class="a-tablelink cursor-interaction" data-trade-group="a" style="font:inherit">${money(tx.a)}</button>`,'截至期末曾完成有效分析')}${stat('其他用户交易量',`<button class="a-tablelink cursor-interaction" data-trade-group="b" style="font:inherit">${money(tx.b)}</button>`,'截至期末无有效分析记录')}${stat('有效分析用户交易量占比',pct(tx.a,tx.total),'两类用户交易量之和 = 平台总量')}</div><div class="a-chart"><h2>每日交易量构成</h2><div id="as-trade-chart" style="width:100%;height:300px" role="img" aria-label="每日平台交易量堆叠图，区分有效分析用户和其他用户"></div></div><div class="a-insight">按统计期末状态固定分组，包含首次分析前的交易。此模块仅随日期变化，始终展示全平台，不受来源筛选影响。</div><details class="a-details"><summary>每日交易明细与统计口径</summary>${table(['日期','有效分析用户交易量','其他用户交易量','平台总量','贡献占比'],tx.days.map(d=>[date(d.date),money(d.a),money(d.b),money(d.total),pct(d.a,d.total)]))}<p>北极星人数统计本期完成分析的人；交易贡献统计截至期末曾完成分析的人，包含本期没再分析的历史用户。</p><p>用户组在所选周期内固定，两组互斥。该指标表示用户群交易贡献，不证明分析促成交易；正式数据使用后台 user_id + date 日汇总。接口缺失显示待获取，不当作 0。</p></details></section>`}
function tradeDrill(tx,c,group,dateFilter=null){
const filtered=tx.records.filter(r=>r.volume>0&&(group==='a'?tx.analyzed.has(r.u.id):!tx.analyzed.has(r.u.id))&&(dateFilter===null||r.date===dateFilter));
const byUser=new Map();for(const r of filtered)byUser.set(r.u.id,(byUser.get(r.u.id)||0)+r.volume);
const total=filtered.reduce((n,r)=>n+r.volume,0),rows=[...byUser].sort((a,b)=>b[1]-a[1]).map(([id,volume])=>({u:users.find(u=>u.id===id)||{id,source:'未知'},volume}));
drawer.open({title:(group==='a'?'有效分析用户':'其他用户')+'交易贡献',description:(dateFilter===null?date(c.start)+'–'+date(c.end-day):date(dateFilter))+' · '+money(total),rows,columns:['用户','来源','交易量','占当前人群交易量'],renderRow:r=>[userButton(r.u),esc(r.u.source),money(r.volume),pct(r.volume,total)],onUser:userTimeline,note:'按交易量排序；后台每日汇总，不推断逐笔成交与分析先后。'});
}

function renderTrade(tx,c){if(!$('#as-trade-chart'))return;$$('[data-trade-group]').forEach(b=>b.onclick=()=>tradeDrill(tx,c,b.dataset.tradeGroup));const host=$('#as-trade-chart');if(!globalThis.echarts){host.innerHTML='<p class="a-muted">图表暂未加载，可展开每日交易明细查看。</p>';return}const color=key=>{const p=document.createElement('span');p.style.color=`var(${key})`;root.appendChild(p);const v=getComputedStyle(p).color;p.remove();return v};tradeChart=echarts.init(host,null,{renderer:'svg'});
const paint=()=>{if(!tradeChart||!host.isConnected)return;tradeChart.setOption({animation:false,aria:{enabled:true},legend:{top:12,data:['有效分析用户','其他用户'],textStyle:{color:color('--a-muted')}},tooltip:{trigger:'axis',confine:true,backgroundColor:color('--a-panel'),borderColor:color('--a-border'),textStyle:{color:color('--a-text')},formatter:p=>{const d=tx.days[p[0].dataIndex];return `${date(d.date)}<br/>有效分析用户：${money(d.a)}<br/>其他用户：${money(d.b)}<br/>平台总量：${money(d.total)}<br/>有效分析用户占比：${pct(d.a,d.total)}`}},grid:{top:66,left:64,right:15,bottom:30},xAxis:{type:'category',data:tx.days.map(d=>date(d.date)),axisLabel:{color:color('--a-muted')},axisLine:{lineStyle:{color:color('--a-border')}}},yAxis:{type:'value',name:'交易量（USD）',nameTextStyle:{color:color('--a-muted')},axisLabel:{color:color('--a-muted'),formatter:v=>v>=1000?(v/1000)+'k':v},splitLine:{lineStyle:{color:color('--a-border')}}},series:[{name:'有效分析用户',type:'bar',stack:'volume',barMaxWidth:34,itemStyle:{color:color('--a-accent')},data:tx.days.map(d=>d.a)},{name:'其他用户',type:'bar',stack:'volume',barMaxWidth:34,itemStyle:{color:color('--a-muted')},data:tx.days.map(d=>d.b)}]},true)};paint();tradeChart.on('click',p=>tradeDrill(tx,c,p.seriesIndex===0?'a':'b',tx.days[p.dataIndex].date));tradeResize=new ResizeObserver(()=>tradeChart&&tradeChart.resize());tradeResize.observe(host);tradeTheme=paint;themeMedia.addEventListener('change',tradeTheme)
}

function northPopulation(c,start=c.start,end=c.end){return users.filter(u=>{const first=u.events.find(e=>e.type==='chip');return first&&u.events.some(e=>e.type==='chip'&&e.t>=start&&e.t<end)})}
function northPeriodComparison(c,all,avgDaa,tx){
if(c.period==='all')return '';
const previousStart=c.start-c.range*day,available=previousStart>=base;
const previousPeople=available?northPopulation(c,previousStart,c.start):null,previousDays=available?computeNorthStar(users,previousStart,c.start):null;
const tradeAvailable=Array.isArray(dataStore.trades)&&dataStore.trades.length&&Math.min(...dataStore.trades.map(t=>t.confirmed_at))<=previousStart;
const previousTrade=tradeAvailable?tradingContribution({...c,start:previousStart,end:c.start}).total:null;
const metrics=[['有效分析用户',all.length,previousPeople?.length,false],['日均有效分析',avgDaa,previousDays?previousDays.reduce((n,d)=>n+d.active_users,0)/previousDays.length:null,false],...(Array.isArray(dataStore.trades)?[['交易量',tx.total,previousTrade,true]]:[])];
return `<div class="a-card"><div class="a-cardhead"><h2>同周期对比</h2><span class="a-muted">本期 ${date(c.start)}–${date(c.end-day)} · 上期 ${date(previousStart)}–${date(c.start-day)}</span></div><div class="a-north-comparison">${metrics.map(([label,current,previous,isMoney])=>{const value=v=>isMoney?money(v):Number.isInteger(v)?fmt(v):v.toFixed(1),max=Math.max(current,previous??0,1),change=previous==null?'数据不足':previous===0?(current===0?'与上期持平':'上期为0，不计算变化率'):(current>=previous?'↑ ':'↓ ')+Math.abs((current-previous)/previous*100).toFixed(1)+'%';return `<div class="a-north-compare-metric"><div><strong>${label}</strong><span class="a-muted">${change}</span></div><div class="a-north-compare-row"><span>本期</span><div class="a-track"><div class="a-fill" style="width:${current/max*100}%"></div></div><strong>${value(current)}</strong></div><div class="a-north-compare-row"><span>上期</span><div class="a-track"><div class="a-fill" style="width:${previous==null?0:previous/max*100}%;background:var(--a-muted)"></div></div><strong>${previous==null?'数据不足':value(previous)}</strong></div></div>`}).join('')}</div><p class="a-details">比较相同长度的完整业务日。交易记录未覆盖上期起点时不比较交易量，避免将未提供数据当作0。</p></div>`;
}
function drawNorth(c){clearNative();let toolbar=$('#as-north-toolbar');if(!toolbar){toolbar=document.createElement('div');toolbar.id='as-north-toolbar';root.querySelector('.a-head').append(toolbar)}toolbar.hidden=false;toolbar.innerHTML=`<div class="a-north-periods" role="group" aria-label="北极星统计周期">${[['all','全周期'],['7','近7天'],['14','近14天'],['30','近30天']].map(([v,label])=>`<button class="a-button" data-north-period="${v}" aria-pressed="${String(c.period)===v}">${label}</button>`).join('')}<button class="a-button a-north-info" aria-label="指标口径" title="周期人数按用户去重；每日人数按天去重。首次与回访在周期内互斥。日均为每日人数之和除以业务日数。全周期仅覆盖已加载历史，统计到最近完整一天。">ⓘ</button></div><div class="a-muted a-north-dates">${date(c.start)}–${date(c.end-day)} · 数据截至 ${clock(asof)} · UTC+7</div>`;toolbar.querySelectorAll('[data-north-period]').forEach(b=>b.onclick=()=>{$('#as-range').value=b.dataset.northPeriod;run()});const tx=tradingContribution(c);const first=u=>u.events.find(e=>e.type==='chip'),all=northPopulation(c),fresh=all.filter(u=>first(u).t>=c.start),returning=all.filter(u=>first(u).t<c.start),prevStart=c.start-c.range*day,previous=prevStart>=base?northPopulation(c,prevStart,c.start):null;const change=previous&&previous.length?((all.length-previous.length)/previous.length*100):null;const comparison=change===null?'上期数据不足，暂不比较':`${change>=0?'↑':'↓'} ${Math.abs(change).toFixed(1)}% · 上期 ${previous.length} 人`;
const byId=new Map(users.map(u=>[u.id,u]));const days=computeNorthStar(all,c.start,c.end).map((d,i)=>({t:c.start+i*day,users:d.active_user_ids.map(id=>byId.get(id)),newUsers:d.new_user_ids.map(id=>byId.get(id)),returning:d.returning_user_ids.map(id=>byId.get(id)),loginUsers:users.filter(u=>u.events.some(e=>e.type==='login'&&e.t>=c.start+i*day&&e.t<c.start+(i+1)*day))}));const avgDaa=days.length?days.reduce((n,d)=>n+d.users.length,0)/days.length:0;
const rowsFor=arr=>arr.map(u=>({u,displaySource:first(u).entry_source}));
$('#as-output').innerHTML=`<div class="a-summary a-four">${stat('周期有效分析用户',`<button class="a-tablelink" id="as-north-yesterday" style="font:inherit">${fmt(all.length)}</button>`,c.period==='all'?'已加载历史内的去重用户':comparison)}${stat('日均有效分析用户',avgDaa.toFixed(1),`${days.length} 个完整业务日日均`)}${stat('周期首次分析用户',`<button class="a-tablelink" id="as-north-new" style="font:inherit">${fmt(fresh.length)}</button>`,'首次有效分析发生在本期')}${stat('周期回访分析用户',`<button class="a-tablelink" id="as-north-return" style="font:inherit">${fmt(returning.length)}</button>`,'首次分析在本期之前')}</div><div class="a-card"><div class="a-cardhead"><h2>每日有效分析用户</h2><div class="a-tabs"><button class="a-button" data-north-trend="total" aria-pressed="${northTrendView==='total'}">总量与均线</button><button class="a-button" data-north-trend="split" aria-pressed="${northTrendView==='split'}">首次 / 回访</button></div></div><div class="a-chart"><div id="as-north-chart" role="img" aria-label="每日有效分析用户数，按当天首次和当天回访用户分解" style="height:300px;width:100%"></div></div><div class="a-insight">本期首次 ${fresh.length} 人 ＋ 历史用户回访 ${returning.length} 人 ＝ 本期有效分析 ${all.length} 人。每日人数不可直接相加作为周期人数。</div></div>${northPeriodComparison(c,all,avgDaa,tx)}${tradeMarkup(tx,c)}<details class="a-card a-details a-north-daily"><summary>每日明细 <span class="a-muted">${days.length} 天 · 点击展开</span></summary>${table(['日期','登录用户','有效分析用户','当天首次','当天回访'],days.map((d,i)=>[date(d.t),`<button class="a-tablelink" data-north-login="${i}">${d.loginUsers.length}</button>`,`<button class="a-tablelink cursor-interaction" data-north-day="${i}">${d.users.length}</button>`,d.newUsers.length,d.returning.length]))}</details>`;
$('#as-north-yesterday').onclick=()=>drill('周期有效分析用户',rowsFor(all),'所选周期内去重用户');$('#as-north-new').onclick=()=>drill('周期首次分析用户',rowsFor(fresh),'首次有效分析发生在所选周期');$('#as-north-return').onclick=()=>drill('周期回访分析用户',rowsFor(returning),'首次分析发生在所选周期之前');$$('[data-north-day]').forEach(b=>b.onclick=()=>{const d=days[+b.dataset.northDay];drill(date(d.t)+' 有效分析用户',rowsFor(d.users),'当日去重用户')});
$$('[data-north-login]').forEach(b=>b.onclick=()=>{const d=days[+b.dataset.northLogin];drill(date(d.t)+' 登录用户',d.loginUsers,'当天登录成功的去重用户')});renderTrade(tx,c);const host=$('#as-north-chart');if(!globalThis.echarts){host.innerHTML='<p class="a-muted">图表组件未加载，下方每日明细可查看。</p>';return}
const color=key=>{const p=document.createElement('span');p.style.color=`var(${key})`;root.appendChild(p);const v=getComputedStyle(p).color;p.remove();return v};nativeChart=echarts.init(host,null,{renderer:'svg'});const paint=()=>{if(!nativeChart||!host.isConnected)return;nativeChart.setOption({animation:false,aria:{enabled:true},legend:{data:northTrendView==='split'?['当天首次','当天回访','每日登录用户']:['有效分析总人数','7日移动均值','每日登录用户'],top:0,textStyle:{color:color('--a-muted')}},tooltip:{trigger:'axis',confine:true,backgroundColor:color('--a-panel'),borderColor:color('--a-border'),textStyle:{color:color('--a-text')},formatter:p=>{const d=days[p[0].dataIndex];return `${date(d.t)}<br/>登录用户：${d.loginUsers.length} 人<br/>有效分析：${d.users.length} 人<br/>当天首次：${d.newUsers.length} 人<br/>当天回访：${d.returning.length} 人`}},grid:{top:48,left:45,right:18,bottom:32},xAxis:{type:'category',data:days.map(d=>date(d.t)),axisLabel:{color:color('--a-muted')},axisLine:{lineStyle:{color:color('--a-border')}}},yAxis:{type:'value',name:'人数',minInterval:1,nameTextStyle:{color:color('--a-muted')},axisLabel:{color:color('--a-muted')},splitLine:{lineStyle:{color:color('--a-border')}}},series:(northTrendView==='split'?[{name:'当天首次',type:'bar',stack:'users',barMaxWidth:34,itemStyle:{color:color('--a-accent')},data:days.map(d=>d.newUsers.length)},{name:'当天回访',type:'bar',stack:'users',barMaxWidth:34,itemStyle:{color:color('--a-green')},data:days.map(d=>d.returning.length)}]:[{name:'有效分析总人数',type:'bar',barMaxWidth:34,itemStyle:{color:color('--a-accent')},data:days.map(d=>d.users.length)},{name:'7日移动均值',type:'line',symbolSize:5,itemStyle:{color:color('--a-green')},data:days.map(d=>{const start=Math.max(Math.floor((base+7*3600000)/day)*day-7*3600000,d.t-6*day),rr=computeNorthStar(users,start,d.t+day);return +(rr.reduce((n,r)=>n+r.active_users,0)/rr.length).toFixed(1)})}]).concat([{name:'每日登录用户',type:'line',symbol:'diamond',symbolSize:5,lineStyle:{type:'dashed'},itemStyle:{color:'#e5a64b'},data:days.map(d=>d.loginUsers.length)}])},true)};paint();$$('[data-north-trend]').forEach(b=>b.onclick=()=>{northTrendView=b.dataset.northTrend;drawNorth(c)});nativeChart.on('click',p=>{const d=days[p.dataIndex];if(p.seriesName==='每日登录用户'){drill(date(d.t)+' 登录用户',d.loginUsers,'当天登录成功的去重用户');return}if(p.seriesType!=='bar')return;const arr=northTrendView==='total'?d.users:p.seriesIndex===0?d.newUsers:d.returning;drill(date(d.t)+' · '+p.seriesName,rowsFor(arr),'当日去重用户')});nativeResize=new ResizeObserver(()=>nativeChart&&nativeChart.resize());nativeResize.observe(host);themeHandler=paint;themeMedia.addEventListener('change',themeHandler)
}

function drawReferral(c){
clearNative();const opts={startAt:c.start,endAt:c.end,asOf:asof,sourceFilter:c.source},r=computeReferral(users,dataStore.referrals??[],opts),sharing=computeSharing(users,dataStore.referrals,opts);
const trackingAvailable=users.some(u=>u.events.some(e=>['share_click','share_complete','invite_visit'].includes(e.type))),relationsAvailable=Array.isArray(dataStore.referrals);
const n=(value)=>trackingAvailable?fmt(value):'待采集',binding=value=>relationsAvailable?fmt(value):'待获取';
$('#as-output').innerHTML=`<div class="a-context"><span class="a-chip">分享与推荐增长</span><span>${date(c.start)}–${date(c.end-day)} · ${esc(c.source==='all'?'全部来源':c.source)}</span></div>
<div class="a-summary a-four">${stat('分享按钮点击',n(sharing.clicks),'主动邀请、信号、倍数入口')}${stat('完成分享操作',n(sharing.shares),'成功复制或调用分享功能，非送达证明')}${stat('分享用户',n(sharing.sharers),'统计期内去重分享者')}${stat('链接访问用户',n(sharing.visitors),'统计期内去重访问者')}</div>
<div class="a-card"><div class="a-cardhead"><h2>分享 → 邀请 → 激活</h2><span class="a-muted">活动次数与用户数分别统计</span></div>${table(['分享点击次数','完成分享次数','链接访问用户','绑定邀请用户','7天有效分析用户'],[[n(sharing.clicks),n(sharing.shares),n(sharing.visitors),binding(r.bound_invitees),binding(r.activated_invitees)]])}<p class="a-details">前三项按当期行为发生时间；绑定与激活按当期首次绑定入组。不同阶段可能跨期，不直接计算逐步转化率。</p></div>
<div class="a-summary a-four">${stat('参与推荐用户',binding(r.advocates),'至少绑定一位被邀请用户')}${stat('绑定邀请用户',binding(r.bound_invitees),'首次绑定关系，按被邀请人去重')}${stat('推荐激活率',relationsAvailable?pct(r.activated_invitees,r.bound_invitees):'—',relationsAvailable?r.activated_invitees+' 位完成有效分析':'需推荐关系接口')}${stat('有效推荐系数 K',relationsAvailable&&r.advocates?r.k_factor.toFixed(2):'—','激活邀请用户 ÷ 参与推荐用户')}</div>
<div class="a-card"><div class="a-cardhead"><h2>各分享功能表现</h2><span class="a-muted">主动按钮 / 信号 / 倍数</span></div>${table(['分享功能','按钮点击','完成分享','链接访问UV（逐链接累计）','绑定用户','激活用户'],sharing.types.map(row=>[SHARE_TYPES[row.type],n(row.clicks),n(row.shares),n(row.visitors),binding(row.bound),binding(row.active)]))}<p class="a-details">功能表访问数按链接UV累计，同一人访问多个链接会重复；顶部访问人数全局去重。无法归因的分享类型不计入功能行。</p></div>
<div class="a-card"><div class="a-cardhead"><h2>邀请链接排行</h2><label>排序<select id="as-link-sort"><option value="bound">绑定人数</option><option value="active">激活人数</option><option value="visitors">访问人数</option></select></label></div><div id="as-link-ranking"></div><p class="a-details">以 referral_link_id 关联，${sharing.unattributed} 位绑定用户缺少链接归因，单独列出。邀请人身份与链接归属须由后端校验。</p></div>
<div class="a-card a-details"><h2>计算口径与采集状态</h2><p>${trackingAvailable?'已取得分享行为记录。':'分享行为尚未采集，不能把未提供数据当成0。'}${relationsAvailable?'已取得推荐关系。':'推荐关系待获取，分享数据仍可独立展示。'}</p><p>绑定后7天内完成有效分析计为激活；尚有 ${r.pending_invitees??0} 位未激活用户观察窗口未结束。</p><p>来源筛选对分享者、访问者分别按各自首次来源过滤，对绑定用户按被邀请者首次来源过滤；这些阶段不是同一人群漏斗。</p><p>点击按钮不代表完成分享；复制链接、分享面板调用成功不代表对方收到。信号与倍数分享分别记录功能类型和内容ID。</p></div>`;
if(!relationsAvailable){$$('#as-output .a-summary').filter(el=>el.textContent.includes('参与推荐用户')).forEach(el=>el.remove());}
if(!trackingAvailable){$$('#as-output .a-summary').filter(el=>el.textContent.includes('分享按钮点击')).forEach(el=>el.remove());}
const renderLinks=()=>{const key=$('#as-link-sort').value,rows=[...sharing.links].sort((a,b)=>b[key]-a[key]||b.bound-a.bound);$('#as-link-ranking').innerHTML=rows.length?table(['链接ID','邀请人','分享功能','完成分享','访问UV','绑定人数','激活人数','激活率','待观察'],rows.map(row=>[esc(row.id==='unattributed'?'未归因链接':row.id),esc(row.inviter||'未知'),esc(SHARE_TYPES[row.type]||'未知'),n(row.shares),n(row.visitors),binding(row.bound),binding(row.active),relationsAvailable?pct(row.active,row.bound):'—',binding(row.pending)])):'<p class="a-empty">当前筛选暂无邀请链接记录。</p>'};$('#as-link-sort').onchange=renderLinks;renderLinks();
}

